/*
 * A047846  Number of successive odd nonprimes (A014076).
 * https://oeis.org/A047846
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A047846: lengths of runs of successive odd composite numbers
 * The sequence is generated by scanning odd integers, treating 1 as
 * composite, and grouping consecutive composites into runs.  The run
 * lengths are stored in a dynamic array and memoized, so repeated
 * calls for any n >= 1 work in O(n) time overall. */

#include <stdlib.h>
#include <stdbool.h>

/*--- helper: test whether an odd number (or 1) is prime ---*/
static bool is_prime_simple(idx_t n)
{
    if (n <= 1) return false;          /* 1 is composite for this sequence */
    if (n == 2) return true;           /* though we never test even numbers */
    if (n % 2 == 0) return false;      /* even numbers are not the inputs */

    /* trial division by odd divisors up to sqrt(n) */
    for (idx_t d = 3; d <= n / d; d += 2)
        if (n % d == 0)
            return false;
    return true;
}

/*--- dynamic array for memoizing run lengths ---*/
static seq_t *runs = NULL;     /* 0‑based array of run lengths          */
static size_t runs_cap = 0;    /* allocated capacity                     */
static idx_t  run_cnt = 0;     /* number of runs already computed       */
static idx_t  next_odd = 1;    /* next odd integer to test             */

/* ensure the array has at least 'needed' slots */
static void ensure_capacity(size_t needed)
{
    if (runs_cap >= needed) return;

    size_t new_cap = runs_cap ? runs_cap : 1;
    while (new_cap < needed) new_cap <<= 1;

    seq_t *tmp = (seq_t *)realloc(runs, new_cap * sizeof(seq_t));
    if (!tmp) exit(1);               /* allocation failure */

    runs      = tmp;
    runs_cap  = new_cap;
}

/*--- the required function ---*/
seq_t a(idx_t n)
{
    if (n == 0) return 0;           /* safety: the OEIS offset starts at 1 */

    size_t req = (size_t)n;         /* index into our 0‑based array */

    /* compute runs until we have the nth one */
    while (run_cnt < req) {
        /* find the start of the next composite run */
        while (is_prime_simple(next_odd))
            next_odd += 2;          /* skip primes (or even numbers) */

        /* count consecutive composite odds */
        seq_t len = 0;
        do {
            ++len;
            next_odd += 2;
        } while (!is_prime_simple(next_odd));

        /* store the length and advance */
        if (runs_cap <= run_cnt) ensure_capacity(run_cnt + 1);
        runs[run_cnt++] = len;
    }

    return runs[req - 1];
}
